#include "ctrosk_gfx.h"

#include <stddef.h>
#include <string.h>

static CtrOskSurface g_dst;

void oskFbBind(const CtrOskSurface *s) { g_dst = *s; }

int oskWidth(void)  { return g_dst.w; }
int oskHeight(void) { return g_dst.h; }

void oskPixel(int x, int y, uint8_t r, uint8_t g, uint8_t b) {
  if (!g_dst.base || x < 0 || x >= g_dst.w || y < 0 || y >= g_dst.h) return;
  uint8_t *o = g_dst.base + (ptrdiff_t)x * g_dst.x_stride
                          + (ptrdiff_t)y * g_dst.y_stride;
  if (g_dst.rgb_first) { o[0] = r; o[1] = g; o[2] = b; }
  else                 { o[0] = b; o[1] = g; o[2] = r; }
}

void oskFill(int x0, int y0, int w, int h, uint8_t r, uint8_t g, uint8_t b) {
  for (int y = y0; y < y0 + h; y++)
    for (int x = x0; x < x0 + w; x++)
      oskPixel(x, y, r, g, b);
}

void oskClear(uint8_t r, uint8_t g, uint8_t b) {
  oskFill(0, 0, g_dst.w, g_dst.h, r, g, b);
}

void oskHLine(int x, int y, int w, uint8_t r, uint8_t g, uint8_t b) {
  oskFill(x, y, w, 1, r, g, b);
}

void oskVLine(int x, int y, int h, uint8_t r, uint8_t g, uint8_t b) {
  oskFill(x, y, 1, h, r, g, b);
}

void oskRRect(int x, int y, int w, int h, uint8_t r, uint8_t g, uint8_t b) {
  if (w < 5 || h < 5) { oskFill(x, y, w, h, r, g, b); return; }
  oskFill(x + 2, y,         w - 4, 1,     r, g, b);  /* top edge    */
  oskFill(x + 1, y + 1,     w - 2, 1,     r, g, b);
  oskFill(x,     y + 2,     w,     h - 4, r, g, b);  /* body        */
  oskFill(x + 1, y + h - 2, w - 2, 1,     r, g, b);
  oskFill(x + 2, y + h - 1, w - 4, 1,     r, g, b);  /* bottom edge */
}

void oskKey3D(int x, int y, int w, int h,
              uint8_t fr, uint8_t fg, uint8_t fb,
              uint8_t hr, uint8_t hg, uint8_t hb,
              uint8_t sr, uint8_t sg, uint8_t sb) {
  oskRRect(x, y + h - 3, w, 3, sr, sg, sb);        /* shadow            */
  oskRRect(x, y, w, h - 2, fr, fg, fb);            /* face              */
  oskHLine(x + 3, y + 1, w - 6, hr, hg, hb);       /* highlight, inset  */
  oskHLine(x + 2, y + 2, w - 4, hr, hg, hb);
}

