void oskChar(int x, int y, char c, uint8_t r, uint8_t g, uint8_t b, int scale) {
  if (c < 32 || c > 126) return;
  const unsigned char *gl = font8x8[(int)c - 32];
  for (int row = 0; row < 8; row++) {
    unsigned char bits = gl[row];
    for (int col = 0; col < 8; col++) {
      if (!(bits & (1 << col))) continue;
      if (scale == 1) oskPixel(x + col, y + row, r, g, b);
      else oskFill(x + col * scale, y + row * scale, scale, scale, r, g, b);
    }
  }
}

void oskText(int x, int y, const char *s, uint8_t r, uint8_t g, uint8_t b, int scale) {
  while (*s) {
    oskChar(x, y, *s, r, g, b, scale);
    x += 8 * scale;
    s++;
  }
}

void oskTextCentered(int x, int y, int w, const char *s,
                     uint8_t r, uint8_t g, uint8_t b, int scale) {
  int tw = (int)strlen(s) * 8 * scale;
  oskText(x + (w - tw) / 2, y, s, r, g, b, scale);
}
